    ('ff46387c-2f1a-5652-89ba-a9c191a9cfb1', 'features', 'Synthetic fixture, not a real source format', null, null, null, '2026-10-23')
insert into core.entity_type (code, software, name, db_table, meaning, source_id) values
    ('features.beam', 'features', 'Beam', 'features.beam', 'A leaf type that attaches to the nearest tabled ancestor (element) across an untabled abstract type.', 'ff46387c-2f1a-5652-89ba-a9c191a9cfb1'),
    ('features.element', 'features', 'Element', 'features.element', 'Root of the fixture hierarchy; carries a label and an optional placement matrix shared by all elements.', 'ff46387c-2f1a-5652-89ba-a9c191a9cfb1'),
    ('features.style', 'features', 'Style', 'features.style', 'A standalone symbol type with no base.', 'ff46387c-2f1a-5652-89ba-a9c191a9cfb1'),
    ('features.wall', 'features', 'Wall', 'features.wall', 'A concrete type that also has a subtype, so its table carries a type_code discriminator. Exercises enums, nullable composites, dates, blobs and arrays.', 'ff46387c-2f1a-5652-89ba-a9c191a9cfb1'),
    ('features.wall_layer', 'features', 'WallLayer', 'features.wall_layer', 'One ordered layer of a wall; a child of a table that has a type_code discriminator.', 'ff46387c-2f1a-5652-89ba-a9c191a9cfb1'),
    ('features.wall_standard', 'features', 'WallStandard', 'features.wall_standard', 'A subtype that adds no fields; its row exists only in the base tables.', 'ff46387c-2f1a-5652-89ba-a9c191a9cfb1')
